/// One diagnostic that moves with the text.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Diagnostic {
    pub start: kate_text::Anchor,
    pub end: kate_text::Anchor,
    pub severity: Severity,
    pub message: String,
    pub source: Option<String>,
}

/// Anchor every diagnostic of `params` in `buf`. A missing severity is Error.
pub fn anchor_diagnostics(buf: &kate_text::TextBuffer, params: &lsp_types::PublishDiagnosticsParams, encoding: PositionEncoding) -> Vec<Diagnostic>
/// Current offsets of one diagnostic, or None when an anchor is stale.
pub fn diagnostic_span(buf: &kate_text::TextBuffer, diagnostic: &Diagnostic) -> Option<kate_text::CharRange>
